INSERT INTO inquiry_templates (id, clinic_id, category, title, content, status, sort_order) VALUES
    ('00000000-0000-0000-0000-000000002201', '00000000-0000-0000-0000-000000000001', 'chief_complaint', '食欲不振（急性）',           'いつ頃から食欲が落ちましたか？完全に食べないのか、減っているだけか確認してください。', 'active', 1),
    ('00000000-0000-0000-0000-000000002202', '00000000-0000-0000-0000-000000000001', 'chief_complaint', '嘔吐（回数・内容物）',       '嘔吐の回数、内容物（食物・胆汁・血液など）、嘔吐のタイミング（食後すぐ・空腹時）を確認してください。', 'active', 2),
    ('00000000-0000-0000-0000-000000002203', '00000000-0000-0000-0000-000000000001', 'chief_complaint', '下痢（性状・頻度）',         '便の性状（軟便・水様便・血便・粘液便）、排便頻度、いつから続いているか確認してください。', 'active', 3),
    ('00000000-0000-0000-0000-000000002204', '00000000-0000-0000-0000-000000000001', 'chief_complaint', '皮膚の痒み・発赤',           '痒がる部位、発症時期、季節性の有無、ノミ・ダニ予防の状況を確認してください。', 'active', 4),
    ('00000000-0000-0000-0000-000000002205', '00000000-0000-0000-0000-000000000001', 'chief_complaint', '排尿異常',                   '排尿回数の変化、尿の色・量、排尿時の痛みの有無、血尿の有無を確認してください。', 'active', 5),
    ('00000000-0000-0000-0000-000000002206', '00000000-0000-0000-0000-000000000001', 'history',         '既往歴確認（手術歴）',       '過去の手術歴（去勢・避妊含む）、入院歴、重大な疾患の既往を確認してください。', 'active', 6),
    ('00000000-0000-0000-0000-000000002207', '00000000-0000-0000-0000-000000000001', 'history',         '予防接種歴確認',             '最終ワクチン接種日、狂犬病予防接種の有無、フィラリア予防の状況を確認してください。', 'active', 7),
    ('00000000-0000-0000-0000-000000002208', '00000000-0000-0000-0000-000000000001', 'current_medications', '現在の投薬状況',         '現在服用中の薬剤名、用量、投与期間、処方元の病院を確認してください。', 'active', 8),
    ('00000000-0000-0000-0000-000000002209', '00000000-0000-0000-0000-000000000001', 'current_medications', 'サプリメント・フード',   '現在与えているサプリメント、療法食、おやつの種類を確認してください。', 'active', 9),
    ('00000000-0000-0000-0000-000000002210', '00000000-0000-0000-0000-000000000001', 'notes',           '生活環境確認',               '室内飼い/外飼い、同居動物の有無、散歩の頻度・時間を確認してください。', 'active', 10)
